// SwarmGodServiceServer is the server API for SwarmGodService service.
// All implementations must embed UnimplementedSwarmGodServiceServer
// for forward compatibility.
//
// ═══════════════════════════════════════════════════════════
//
//	SwarmGodService — สัญญากลางเดียวที่ Python cockpit ↔ Go core
//	ทุก RPC ต้องแนบ metadata: authorization=Bearer <session-token>
//	ช่องทางเป็น mTLS (ดู SECURITY.md)
//
// ═══════════════════════════════════════════════════════════
type SwarmGodServiceServer interface {
	// ── streams (core → cockpit) ──
	SubscribeTelemetry(*SubscribeTelemetryRequest, grpc.ServerStreamingServer[Telemetry]) error
	SubscribeEvents(*EventSubscribeRequest, grpc.ServerStreamingServer[Event]) error
	GetFleetSnapshot(context.Context, *FleetSnapshotRequest) (*FleetSnapshot, error)
	// ── fleet management ──
	Connect(context.Context, *ConnectRequest) (*CommandResult, error)
	Disconnect(context.Context, *DisconnectRequest) (*CommandResult, error)
	// ── flight commands (unary + ACK; ผ่าน safety envelope) ──
	Arm(context.Context, *ArmRequest) (*CommandResult, error)
	Disarm(context.Context, *DisarmRequest) (*CommandResult, error)
	Kill(context.Context, *KillRequest) (*CommandResult, error)
	Takeoff(context.Context, *TakeoffRequest) (*CommandResult, error)
	Land(context.Context, *LandRequest) (*CommandResult, error)
	ReturnToLaunch(context.Context, *RtlRequest) (*CommandResult, error)
	Hold(context.Context, *HoldRequest) (*CommandResult, error)
	Goto(context.Context, *GotoRequest) (*CommandResult, error)
	ChangeAlt(context.Context, *ChangeAltRequest) (*CommandResult, error)
	EqualizeAlt(context.Context, *EqualizeAltRequest) (*CommandResult, error)
	// Roadmap RPC: ยังไม่มี handler ใน core ปัจจุบัน (client จะได้ Unimplemented)
	ChangeSpeed(context.Context, *ChangeSpeedRequest) (*CommandResult, error)
	RcMove(context.Context, *RcMoveRequest) (*CommandResult, error)
	// Roadmap RPC: ยังไม่มี handler ใน core ปัจจุบัน
	SetYaw(context.Context, *SetYawRequest) (*CommandResult, error)
	StopAll(context.Context, *StopAllRequest) (*CommandResult, error)
	SetMode(context.Context, *SetModeRequest) (*CommandResult, error)
	// ── mission (roadmap; ยังไม่มี handler ใน core ปัจจุบัน) ──
	UploadMission(context.Context, *UploadMissionRequest) (*CommandResult, error)
	MissionControl(context.Context, *MissionControlRequest) (*CommandResult, error)
	Orbit(context.Context, *OrbitRequest) (*CommandResult, error)
	// ── run-based mission (Fast-Track V2 F3: Core run identity + Start/Cancel/Query) ──
	// ยังไม่ถือ flight authority — Go เป็น shadow จน F4 cutover
	StartMission(context.Context, *StartMissionRequest) (*StartMissionResponse, error)
	CancelMission(context.Context, *CancelMissionRequest) (*CommandResult, error)
	GetMissionState(context.Context, *GetMissionStateRequest) (*MissionStateResponse, error)
	// ── payload ──
	Gimbal(context.Context, *GimbalRequest) (*CommandResult, error)
	Servo(context.Context, *ServoRequest) (*CommandResult, error)
	// ── params ──
	ParamGet(context.Context, *ParamGetRequest) (*ParamValue, error)
	ParamSet(context.Context, *ParamSetRequest) (*CommandResult, error)
	ParamList(context.Context, *ParamListRequest) (*ParamListResponse, error)
	// ── geofence ──
	SetGeofence(context.Context, *SetGeofenceRequest) (*CommandResult, error)
	// ── swarm ──
	SetLeader(context.Context, *SetLeaderRequest) (*CommandResult, error)
	SetSwarmConfig(context.Context, *SwarmConfig) (*CommandResult, error)
	SwarmControl(context.Context, *SwarmControlRequest) (*CommandResult, error)
	GetSwarmState(context.Context, *SwarmStateRequest) (*SwarmState, error)
	mustEmbedUnimplementedSwarmGodServiceServer()
}

